import re
from typing import Tuple, List, Dict

def check_password_strength(
    password: str,
    min_length: int = 8,
    require_uppercase: bool = True,
    require_lowercase: bool = True,
    require_digits: bool = True,
    require_special: bool = True
) -> Tuple[int, str, bool, List[str], Dict[str, bool]]:
    """
    检查密码强度。
    """
    if not password:
        return 0, 'very_weak', False, ['Password cannot be empty'], {}

    suggestions = []
    checks = {
        'length': len(password) >= min_length,
        'uppercase': bool(re.search(r'[A-Z]', password)),
        'lowercase': bool(re.search(r'[a-z]', password)),
        'digits': bool(re.search(r'\d', password)),
        'special': bool(re.search(r'[!@#$%^&*(),.?":{}|<>]', password))
    }

    # 计算分数
    score = 0

    # 长度分数（最高40分）
    length = len(password)
    if length >= min_length:
        score += 20
    if length >= min_length + 4:
        score += 10
    if length >= min_length + 8:
        score += 10
    else:
        suggestions.append(f'Increase length to at least {min_length} characters')

    # 复杂度分数（每种类型10分）
    if checks['lowercase']:
        score += 10
    elif require_lowercase:
        suggestions.append('Add lowercase letters')

    if checks['uppercase']:
        score += 10
    elif require_uppercase:
        suggestions.append('Add uppercase letters')

    if checks['digits']:
        score += 10
    elif require_digits:
        suggestions.append('Add numbers')

    if checks['special']:
        score += 10
    elif require_special:
        suggestions.append('Add special characters (!@#$%^&*)')

    # 额外分数
    if length > 12:
        score += 10
    if len(set(password)) > len(password) * 0.7:  # 高熵值
        score += 10

    score = min(score, 100)

    # 确定强度等级
    if score >= 90:
        strength = 'very_strong'
    elif score >= 70:
        strength = 'strong'
    elif score >= 50:
        strength = 'medium'
    elif score >= 30:
        strength = 'weak'
    else:
        strength = 'very_weak'

    # 检查是否通过策略
    passed = (
        checks['length'] and
        (not require_uppercase or checks['uppercase']) and
        (not require_lowercase or checks['lowercase']) and
        (not require_digits or checks['digits']) and
        (not require_special or checks['special'])
    )

    return score, strength, passed, suggestions, checks
